fun <T : Titled> label(item: T): String {
  return item.badge(1)
}

fun <T> firstIndex(items: List<T>, of: T): Int? {
  val item = of
  var index = 0
  for (candidate in items) {
    if (candidate == item) {
      return index
    }
    index = index + 1
  }
  return null
}

