}

fun demo(post: Post): String {
  val api = API("/feeds")
  val names = "${codecName(post)} ${api.describe(Page(listOf(post)))}"
  val titles = PrefKey.entries.map({ it.title })
  val at = firstIndex(PrefKey.entries, PrefKey.replies) ?: -1
  val found = firstIndex(listOf(post), post) ?: -1
  return "${label(post)} ${describe(post)} ${titles.size} ${at} ${found} ${names}"
}

